import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as d,X as i}from"./chunks/vendor-vueuse.XPft87tp.js";const m=JSON.parse('{"title":"Vue3 为什么比 Vue2 打包体积更小","description":"","frontmatter":{},"headers":[],"relativePath":"vue/vue-bundle-size.md","filePath":"vue/vue-bundle-size.md","lastUpdated":1785917016000}'),s={name:"vue/vue-bundle-size.md"};function o(r,e,n,l,p,h){return d(),a("div",null,e[0]||(e[0]=[i('<h1 id="vue3-为什么比-vue2-打包体积更小" tabindex="-1">Vue3 为什么比 Vue2 打包体积更小 <a class="header-anchor" href="#vue3-为什么比-vue2-打包体积更小" aria-label="Permalink to &quot;Vue3 为什么比 Vue2 打包体积更小&quot;">​</a></h1><h3 id="tree-shaking-支持" tabindex="-1">Tree-Shaking 支持 <a class="header-anchor" href="#tree-shaking-支持" aria-label="Permalink to &quot;Tree-Shaking 支持&quot;">​</a></h3><p>Vue3 采用 ES Module 格式发布，天然支持 Tree-Shaking。打包工具（如 Webpack、Rollup、Vite）在构建阶段通过静态分析 <code>import</code> / <code>export</code> 语句，可以精确判断哪些代码被实际引用，未被引用的部分会在最终产物中被剔除。</p><p>Vue2 发布的是 UMD 格式的产物。UMD 的设计目标是同时兼容 CommonJS 和 AMD，它的模块边界在运行时才解析，打包工具无法在编译阶段安全地剔除未使用代码。因此即使项目只用到了 Vue 的一小部分 API，整个运行时代码都会被打进去。</p><p>关于几种模块格式的区别：</p><table tabindex="0"><thead><tr><th>格式</th><th>环境</th><th>导入/导出</th><th>加载机制</th></tr></thead><tbody><tr><td>CommonJS</td><td>Node.js</td><td><code>require</code> / <code>module.exports</code></td><td>运行时加载，同步</td></tr><tr><td>AMD</td><td>浏览器</td><td><code>define</code> / <code>require</code></td><td>运行时加载，异步</td></tr><tr><td>UMD</td><td>浏览器 + Node.js</td><td>兼容 CommonJS 和 AMD</td><td>运行时加载</td></tr><tr><td>ES Module</td><td>浏览器 + Node.js</td><td><code>export</code> / <code>import</code></td><td>编译时加载，异步，支持 Tree-Shaking</td></tr></tbody></table><p>CommonJS 的同步加载在服务端是合理的——模块文件在本地磁盘，读取速度很快。但在浏览器端，同步加载意味着网络请求期间会阻塞页面渲染，所以 AMD 和 ES Module 都采用异步加载。</p><h3 id="核心代码重写" tabindex="-1">核心代码重写 <a class="header-anchor" href="#核心代码重写" aria-label="Permalink to &quot;核心代码重写&quot;">​</a></h3><p>Vue3 用 TypeScript 重写了全部核心逻辑，代码结构更紧凑。以响应式系统为例：Vue2 基于 <code>Object.defineProperty</code> 的实现需要递归遍历对象的所有属性，初始化阶段就要完成全部劫持；Vue3 基于 <code>Proxy</code> 的实现按需代理，同等功能所需代码量更少，同时去掉了 <code>$set</code>、<code>$delete</code> 等补充 API。</p><h3 id="按需引入" tabindex="-1">按需引入 <a class="header-anchor" href="#按需引入" aria-label="Permalink to &quot;按需引入&quot;">​</a></h3><p>Vue3 的 Composition API 天然支持按需引入。从 <code>vue</code> 中直接导入所需函数即可：</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { ref, computed, watch } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;vue&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>只有被 <code>import</code> 的 API 会出现在最终打包产物中。类似地，第三方 UI 组件库（如 Element Plus）也采用 ES Module 导出，配合支持 Tree-Shaking 的构建工具，可以做到只打包实际使用的组件：</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { Button, Dialog } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;element-plus&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Vue2 的按需引入依赖插件（如 <code>babel-plugin-component</code>）在编译阶段做导入路径转换，配置相对复杂，且容易因配置遗漏引入额外的代码。</p><h3 id="对比-vue2-的体积下降" tabindex="-1">对比 Vue2 的体积下降 <a class="header-anchor" href="#对比-vue2-的体积下降" aria-label="Permalink to &quot;对比 Vue2 的体积下降&quot;">​</a></h3><p>三项优化叠加后，一个最小 Vue3 项目的运行时体积相比 Vue2 可以减少约 40%。Tree-Shaking 决定产物基线，核心代码重写降低单位功能的代码量，按需引入确保只携带项目实际使用的部分。</p>',17)]))}const k=t(s,[["render",o]]);export{m as __pageData,k as default};
